function emailErrors(r) {
  const errors=[];
  const add=(campo,mensagem)=>errors.push({codigo:'EMAIL_CONTENT',campo,mensagem});
  if(!['fish','aristo'].includes(r.marca))add('marca','Escolha Fishermans ou O Aristocrata.');
  if(!String(r.nome||'').trim()||String(r.nome).length>120)add('nome','Nome obrigatório, até 120 caracteres.');
  if(!String(r.assunto||'').trim()||String(r.assunto).length>150)add('assunto','Assunto obrigatório, até 150 caracteres.');
  if(!String(r.corpo||'').trim()||String(r.corpo).length>200000)add('corpo','Corpo obrigatório, até 200 mil caracteres.');
  if(/<\s*(script|iframe|object|embed|form|input|base|meta)\b|\bon[a-z]+\s*=|javascript\s*:|data\s*:/i.test(r.corpo||''))add('corpo','Remova scripts, formulários e conteúdo interativo do e-mail.');
  // Only documented transaction variables; arbitrary Go-template functions are not accepted by this editor.
  for(const t of [r.corpo,r.assunto,r.rodape]) {
    const leftovers=String(t||'').replace(/\{\{\s*\.Tx\.Data\.[a-zA-Z][a-zA-Z0-9_]{0,63}\s*\}\}/g,'');
    if(leftovers.includes('{{')||leftovers.includes('}}'))add('corpo','Use variáveis no formato {{ .Tx.Data.first_name }}.');
  }
  for(const b of r.botoes||[])if(b.tipo!=='url'||!/^https:\/\/[^\s<>"']+$/.test(b.valor||''))add('botoes','Botões de e-mail precisam de um link HTTPS.');
  if(GEC.hasEnvelope(r))errors.push(...GEC.envelopeErrors(r));
  errors.push(...GEC.documentErrors(r));
  return errors;
}

